/**
 * @brief set upcall notifier vector
 *
 * This is the API that helps to switch the notifer vecotr. If this API is
 * not called, the hypervisor will use the default notifier vector(0xF3)
 * to notify the SOS kernel.
 *
 * @param vm Pointer to VM data structure
 * @param param the expected notifier vector from guest
 *
 * @pre Pointer vm shall point to SOS_VM
 * @return 0 on success, non-zero on error.
 */int32_t hcall_set_callback_vector(const struct acrn_vm *vm, uint64_t param)
{
	int32_t ret;

	if (!is_sos_vm(vm)) {
		pr_err("%s: Targeting to service vm", __func__);
	        ret = -EPERM;
	} else if ((param > NR_MAX_VECTOR) || (param < VECTOR_DYNAMIC_START)) {
		pr_err("%s: Invalid passed vector\n");
		ret = -EINVAL;
	} else {
		set_vhm_notification_vector((uint32_t)param);
		ret = 0;
	}

	return ret;
}

/**
 * @brief Set interrupt mapping info of ptdev.
 *
 * @param vm Pointer to VM data structure
 * @param vmid ID of the VM
 * @param param guest physical address. This gpa points to data structure of
 *              hc_ptdev_irq including intr remapping info
 *
 * @pre Pointer vm shall point to SOS_VM
 * @return 0 on success, non-zero on error.
 */int32_t hcall_set_ptdev_intr_info(struct acrn_vm *vm, uint16_t vmid, uint64_t param)
{
	int32_t ret;
	struct hc_ptdev_irq irq;
	struct acrn_vm *target_vm = get_vm_from_vmid(vmid);

	(void)memset((void *)&irq, 0U, sizeof(irq));
	if (!is_valid_vm(target_vm)) {
	        ret = -1;
	} else if (copy_from_gpa(vm, &irq, param, sizeof(irq)) != 0) {
		pr_err("%s: Unable copy param to vm\n", __func__);
	        ret = -1;
	} else {
		/* Inform vPCI about the interupt info changes */
#ifndef CONFIG_PARTITION_MODE
		vpci_set_ptdev_intr_info(target_vm, irq.virt_bdf, irq.phys_bdf);
#endif

		if (irq.type == IRQ_INTX) {
			ret = ptirq_add_intx_remapping(target_vm, irq.is.intx.virt_pin,
					irq.is.intx.phys_pin, irq.is.intx.pic_pin);
		} else if (((irq.type == IRQ_MSI) || (irq.type == IRQ_MSIX)) &&
				(irq.is.msix.vector_cnt <= CONFIG_MAX_MSIX_TABLE_NUM)) {
			ret = ptirq_add_msix_remapping(target_vm,
					irq.virt_bdf, irq.phys_bdf,
					irq.is.msix.vector_cnt);
		} else {
			pr_err("%s: Invalid irq type: %u or MSIX vector count: %u\n",
					__func__, irq.type, irq.is.msix.vector_cnt);
			ret = -1;
		}
	}

	return ret;
}

/**
 * Iterate through the channels and find the largest led count.
 *
 * @param    ws2811  ws2811 instance pointer.
 *
 * @returns  Maximum number of LEDs in all channels.
 */static int max_channel_led_count(ws2811_t *ws2811)
{
    int chan, max = 0;

    for (chan = 0; chan < RPI_PWM_CHANNELS; chan++)
    {
        if (ws2811->channel[chan].count > max)
        {
            max = ws2811->channel[chan].count;
        }
    }

    return max;
}

/**
 * add_node_to_list
 *
 * This function is used to add node to tlist, compress_tlist_tle and compress_tlist.
 * It also set data for mapcell.
 *
 * @param[in] expr Expression
 * @param[in,out] tlist Flattened tlist
 * @param[in,out] mapcells The mapping cell which is corresponding to the expr
 * @param[in,out] compress_tlist_tle Compressed child tlist with target entry
 * @param[in,out] compress_tlist Compressed child tlist without target entry
 * @param[in] sgref Sort group reference for target entry
 * @param[in] is_agg_ope True if combination of aggregate function and operators
 * @param[in] allow_duplicate Allow or not allow a target can be duplicated in grouping target list
 */static void
add_node_to_list(Expr *expr, List **tlist, Mappingcells * *mapcells, List **compress_tlist_tle, List **compress_tlist, Index sgref, bool is_agg_ope, bool allow_duplicate)
{
	/* Non-agg group by target or non-split agg such as sum or count */
	TargetEntry *tle_temp;
	TargetEntry *tle;
	int			target_num = 0;
	int			next_resno = list_length(*tlist) + 1;
	int			next_resno_temp = list_length(*compress_tlist_tle) + 1;

	tle = spd_tlist_member(expr, *tlist, &target_num);
	/* original */
	if (allow_duplicate || !tle)
	{
		if (allow_duplicate)
			target_num = list_length(*tlist);

		/*
		 * When expression is a combination of operator and aggregate
		 * function, no need to add to tlist because the whole expression has
		 * been added in spd_add_to_flat_tlist.
		 */
		if (is_agg_ope == false)
		{
			tle = makeTargetEntry(copyObject(expr),
								  next_resno++,
								  NULL,
								  false);
			tle->ressortgroupref = sgref;
			*tlist = lappend(*tlist, tle);
		}
		else
			target_num = list_length(*tlist) - 1;
	}
	else if (tle)
	{
		target_num = list_length(*tlist) - 1;
	}
	(*mapcells)->aggtype = NON_AGG_FLAG;
	(*mapcells)->original_attnum = target_num;
	/* div tlist */
	tle_temp = spd_tlist_member(expr, *compress_tlist_tle, &target_num);
	if (allow_duplicate || !tle_temp)
	{
		tle_temp = makeTargetEntry(copyObject(expr),
								   next_resno_temp++,
								   NULL,
								   false);
		tle_temp->ressortgroupref = sgref;
		*compress_tlist_tle = lappend(*compress_tlist_tle, tle_temp);
		*compress_tlist = lappend(*compress_tlist, expr);
	}
	else if (tle_temp)
	{
		/*
		 * If var was added inside extract_expr, ressortgroupref was not set.
		 * we need to set it at this place
		 */
		if (sgref > 0)
			tle_temp->ressortgroupref = sgref;
	}

	/*
	 * If allow duplicate, so need to change mapping to the last of
	 * compress_tlist.
	 */
	if (allow_duplicate)
	{
		(*mapcells)->mapping[AGG_SPLIT_NONE] = list_length(*compress_tlist) - 1;
	}
	else
	{
		(*mapcells)->mapping[AGG_SPLIT_NONE] = target_num;
	}
}

/**
 * 功能：获取指定下标的元素
 * 参数：sequenceList 顺序表对象 index 下标 element 通过此引用参数返回元素
 * 返回值：成功返回OK 否则返回ERROR1
*/Status getElement(SequenceList sequenceList,int index,ElementType &element){
    //如果下标不合法那么直接返回ERROR1
    if((index > (sequenceList.length - 1)) || (index < 0)){
        return ERROR1;
    }else{
        //通过引用参数element返回元素
        element = sequenceList.element[index];
        return OK;
    }
}

/**
 * sw_cfg_port_based - configure switch port based priority
 * @sw:		The switch instance.
 * @port:	The port index.
 * @prio:	The priority to set.
 *
 * This routine configures the port based priority of the switch.
 */static void sw_cfg_port_based(struct ksz_sw *sw, uint port, u8 prio)
{
	SW_D data;

	if (prio > PORT_BASED_PRIO_M)
		prio = PORT_BASED_PRIO_M;

	port_r(sw, port, P_PRIO_CTRL, &data);
	data &= ~(PORT_BASED_PRIO_M << PORT_BASED_PRIO_S);
	data |= prio << PORT_BASED_PRIO_S;
	port_w(sw, port, P_PRIO_CTRL, data);

	sw->info->port_cfg[port].port_prio = prio;
}

