/**
 * API to stop ASO access using ASO SQ.
 *
 * @param[in] sh
 *   Pointer to shared device context.
 *
 * @return
 *   0 on success, a negative errno value otherwise and rte_errno is set.
 */int
mlx5_aso_queue_stop(struct mlx5_dev_ctx_shared *sh)
{
	int retries = 1024;

	if (!sh->aso_age_mng->aso_sq.sq_obj.sq)
		return -EINVAL;
	rte_errno = 0;
	while (--retries) {
		rte_eal_alarm_cancel(mlx5_flow_aso_alarm, sh);
		if (rte_errno != EINPROGRESS)
			break;
		rte_pause();
	}
	return -rte_errno;
}

/**
 * @brief Enable or Disable the specified LCD interrupts.
 * @param LCD_INT: Specify the LCD interrupt sources that is to be enabled or disabled.
 *   This parameter can be any combination of the following values:
 *     @arg LCD_INT_UDDIE : Update Display Done Interrupt Enable
 *     @arg LCD_INT_SOFIE : Start of Frame Interrupt Enable
 * @param NewState: This parameter can be ENABLE or DISABLE.
 * @retval None
 ************************************************************************************************************/void LCD_IntConfig(u32 LCD_INT, ControlStatus NewState)
{
  /* Check the parameters                                                                                   */
  Assert_Param(IS_LCD_INT(LCD_INT));
  Assert_Param(IS_CONTROL_STATUS(NewState));

  if (NewState != DISABLE)
  {
    HT_LCD->IER |= LCD_INT;
  }
  else
  {
    HT_LCD->IER &= ~LCD_INT;
  }
}

/**
 * Scale the contents of a vector.
 *
 * For a vector \f$x\f$ and a scalar \f$ \alpha \f$, this computes the
 * scalar-vector product \f$\alpha x\f$ and stores the result in \f$x\f$.
 *
 * \param[in] n         Length of the vector
 * \param[in] alpha     Scalar to apply
 * \param[in,out] x     Vector to scale
 * \param[in] inc_x     Increment (stride) of x vector.
 *
 * If inc_x is negative, then iteration is backwards starting with element
 * (1 - n) * inc_x. For example, n = 5 and inc_x = -2 would iterate over
 * x[8], x[6], x[4], x[2], x[0].
 *
 * Note: The reference implementation does not support negative increments.
 * It is added here because the operation is used higher level BLAS
 * functions. (Netlib just re-implements it.)
 */void
sp_blas_sscal(
    len_t n,
    float alpha,
    float * const x,
    len_t inc_x)
{
    SP_ASSERT_VALID_DIM(n);
    SP_ASSERT_VALID_INC(inc_x);

    if (inc_x == 1) {
        sp_blas_sscal_inc1(n, alpha, x);
    } else {
        sp_blas_sscal_incx(n, alpha, x, inc_x);
    }

fail:
    return;
}

