/**
 *free_dlistint - function that frees a listint_t list
 *
 *@head: pointer to head element in list
 */void free_dlistint(stack_t *head)
{
	stack_t *nodo;

	while (head != '\0')
	{
		nodo = head->next;
		free(head);
		head = nodo;
	}
}

/**
* free_list - a function that frees a dlistint_t list.
* @head: the head of the list.
*
* Return: void
*/void free_list(stack_t *head)
{
	stack_t *temp;

	while (head != NULL)
	{
		temp = head->next;
		free(head);
		head = temp;
	}
}

