/**
 * set_bit - sets the value of a bit to 1 at a given index
 * @n: number
 * @index: is the index, starting from 0 of the bit you want to set
 * Return: 1 if it worked, or -1 if an error occurred
 */int set_bit(unsigned long int *n, unsigned int index)
{

	if (index > (8 * (sizeof(*n)) - 1))
	{
		return (-1);
	}
	*n = *n | 1 << index;
	return (1);
}

/**
 *	__kfree_skb - private function
 *	@skb: buffer
 *
 *	Free an sk_buff. Release anything attached to the buffer.
 *	Clean the state. This is an internal helper function. Users should
 *	always call kfree_skb
 */void __kfree_skb(struct sk_buff *skb)
{
	//释放skb 数据区和执行其他一些析构函数
	skb_release_all(skb);
	//释放skb 自身占用的内存
	kfree_skbmem(skb);
}

/**
 * free_list - function that
 * frees a list_t list.
 * @head: pointer to the head of the list
 * Return: void
 */void free_list(hash_node_t *head)
{
	hash_node_t *temp;

	temp = head;
	while (head)
	{

		temp = head;
		head = head->next;
		/*freeing the content*/
		if (temp->key)
			free(temp->key);
		if (temp->value)
			free(temp->value);
		free(temp);
	}
}

/**
 * @brief offline vcpu from SOS
 *
 * The function offline specific vcpu from SOS.
 *
 * @param vm Pointer to VM data structure
 * @param lapicid lapic id of the vcpu which wants to offline
 *
 * @pre Pointer vm shall point to SOS_VM
 * @return 0 on success, non-zero on error.
 */int32_t hcall_sos_offline_cpu(struct acrn_vm *vm, uint64_t lapicid)
{
	struct acrn_vcpu *vcpu;
	uint16_t i;
	int32_t ret = 0;

	pr_info("sos offline cpu with lapicid %lld", lapicid);

	foreach_vcpu(i, vm, vcpu) {
		if (vlapic_get_apicid(vcpu_vlapic(vcpu)) == lapicid) {
			/* should not offline BSP */
			if (vcpu->vcpu_id == BOOT_CPU_ID) {
				ret = -1;
				break;
			}
			pause_vcpu(vcpu, VCPU_ZOMBIE);
			reset_vcpu(vcpu);
			offline_vcpu(vcpu);
		}
	}

	return ret;
}

