/**
 * Return the sum of the absolute values of a vector (1-norm).
 *
 * \param[in] n         Number of elements add
 * \param[in] x         Pointer to the first element of the vector
 * \param[in] inc_x     Increment (stride) to sum over
 * \returns             Sum of absolute values of the vector elements
 */float
sp_blas_sasum(
    len_t n,
    const float * const x,
    len_t inc_x)
{
    float result = 0.0f;

    SP_ASSERT_VALID_DIM(n);
    SP_ASSERT_VALID_INC(inc_x);

    if (inc_x == 1) {
        result = sp_blas_sasum_inc1(n, x);
    } else {
        result = sp_blas_sasum_incx(n, x, inc_x);
    }

fail:
    return result;
}

/**
 * get_nodeint_at_index - go through the nth node of a list
 * @head: pointer to the first node
 * @index: index of the node
 * Return: Address of the nth node that specifies the index parameter
 */listint_t *get_nodeint_at_index(listint_t *head, unsigned int index)
{
	unsigned int i;
	listint_t *temp = head;

	for (i = 0; i < index && temp != NULL; i++)
	{
		temp = temp->next;
	}
	if (temp == NULL)
		return (NULL);
	else
		return (temp);
}

/**
  * @brief  De-initialize USART registers (Registers restored to their default values).
  * @param  USARTx USART Instance
  * @retval An ErrorStatus enumeration value:
  *          - SUCCESS: USART registers are de-initialized
  *          - ERROR: USART registers are not de-initialized
  */ErrorStatus LL_USART_DeInit(USART_TypeDef *USARTx)
{
  ErrorStatus status = SUCCESS;

  /* Check the parameters */
  assert_param(IS_UART_INSTANCE(USARTx));

  if (USARTx == USART1)
  {
    /* Force reset of USART clock */
    LL_APB2_GRP1_ForceReset(LL_APB2_GRP1_PERIPH_USART1);

    /* Release reset of USART clock */
    LL_APB2_GRP1_ReleaseReset(LL_APB2_GRP1_PERIPH_USART1);
  }
  else
  {
    status = ERROR;
  }

  return (status);
}

